void sctp_assoc_update(struct sctp_association *asoc, struct sctp_association *new) {
    struct sctp_transport *t, *next;

    /* Copy new parameters from 'new' to 'asoc' */
    memcpy(&asoc->params, &new->params, sizeof(asoc->params));

    /* Remove peer addresses in 'asoc' that are not in 'new' */
    list_for_each_entry_safe(t, next, &asoc->peer.transport_addr_list, transports) {
        int found = 0;
        struct sctp_transport *t2;

        list_for_each_entry(t2, &new->peer.transport_addr_list, transports) {
            if (!memcmp(&t->saddr, &t2->saddr, sizeof(t->saddr)) &&
                t->sport == t2->sport) {
                found = 1;
                break;
            }
        }

        if (!found) {
            list_del(&t->transports);
            kfree(t);
        }
    }

    if (asoc->state == SCTP_STATE_ESTABLISHED) {
        asoc->c.sackrcvd = 0;
        asoc->c.sacksent = 0;
        asoc->c.rewnd = asoc->c.wnd;
        asoc->next_tsn = new->next_tsn;
        sctp_ssnmap_clear(&asoc->ssn_map);
        sctp_ulpq_flush(&asoc->ulpq);
        asoc->error_count = 0;
    } else {
        list_splice_tail_init(&new->peer.transport_addr_list, &asoc->peer.transport_addr_list);
        sctp_ssnmap_copy(&asoc->ssn_map, &new->ssn_map);
        asoc->assoc_id = new->assoc_id;
    }

    /* Update SCTP-AUTH related peer parameters */
    asoc->auth_params = new->auth_params;
    asoc->asconf_key = new->asconf_key;
    asoc->active_key = new->active_key;
    asoc->active_key_id = new->active_key_id;
}

void sctp_update_association(struct sctp_association *asoc, struct sctp_association *new) {
    struct sctp_transport *t, *tmp;

    /* Copy new parameters from 'new' to 'asoc' */
    asoc->rwnd = new->rwnd;
    asoc->ssthresh = new->ssthresh;
    asoc->partial_failure_point = new->partial_failure_point;
    asoc->c.sackdelay = new->c.sackdelay;
    asoc->c.sackfreq = new->c.sackfreq;
    asoc->c.pathmaxrxt = new->c.pathmaxrxt;
    asoc->c.minrto = new->c.minrto;
    asoc->c.maxrto = new->c.maxrto;
    asoc->c.maxrto = new->c.maxrto;
    asoc->c.max_burst = new->c.max_burst;

    list_for_each_entry(t, &new->peer.addrs, list) {
        struct sctp_transport *tmp_transport = sctp_transport_lookup(&asoc->peer.addrs, t->ipall);

        if (!tmp_transport) {
            t = kzalloc(sizeof(struct sctp_transport), GFP_KERNEL);
            *t = *new->initiate_tag; /* Copy the transport from new */
            sctp_transport_add(&asoc->peer.addrs, t);
        }
    }

    list_for_each_entry_safe(t, tmp, &asoc->peer.addrs, list) {
        struct sctp_transport *tmp_transport = sctp_transport_lookup(&new->peer.addrs, t->ipall);

        if (!tmp_transport) {
            sctp_transport_del(&asoc->peer.addrs, t);
            kfree(t);
        }
    }

    if (asoc->state >= SCTP_STATE_ESTABLISHED) {
        asoc->c.next_tsn = new->c.next_tsn;
        sctp_ssnmap_clear(&asoc->ssnmap);
        sctp_flush_ulpq(&asoc->ulpq);
        asoc->stats.ecount = 0;
    } else {
        asoc->assoc_id = new->assoc_id;
        sctp_ssnmap_init(&asoc->ssnmap, new->ssnmap);
    }

    if (new->auth_key) {
        asoc->auth_key = new->auth_key;
        new->auth_key = NULL;
    }

    asoc->active_key_id = new->active_key_id;
    asoc->peer.auth_info = new->peer.auth_info;
    asoc->peer.active_key_id = new->peer.active_key_id;
}

void sctp_assoc_update(struct sctp_association *asoc, struct sctp_association *new) {
    struct sctp_transport *t, *temp;
    struct sctp_stream_out *out;
    struct sctp_stream_in *in;

    /* Copy new parameters from 'new' to 'asoc' */
    asoc->rwnd = new->rwnd;
    asoc->ssthresh = new->ssthresh;
    asoc->cwnd = new->cwnd;
    asoc->partial_failure = new->partial_failure;

    /* Remove peer addresses not in 'new' */
    sctp_transport_for_each_safe(t, temp, &asoc->peer.transport_addr_list) {
        if (!sctp_transport_lookup(t->ipall, t->sport, t->v4sin, t->v6sin6, &new->peer.transport_addr_list)) {
            sctp_transport_free(t);
        }
    }

    if (asoc->state == SCTP_STATE_ESTABLISHED) {
        asoc->next_tsn = new->next_tsn;
        asoc->ssnmap = new->ssnmap;
        asoc->ulpq = new->ulpq;

        /* Flush ULP reassembly queue */
        sctp_ulpq_flush(asoc->ulpq);

        asoc->overall_error_count = 0;
    } else {
        sctp_transport_for_each(t, &new->peer.transport_addr_list) {
            struct sctp_transport *new_t = sctp_transport_dup(t);
            sctp_assoc_add_transport(asoc, new_t);
        }

        if (asoc->state < SCTP_STATE_ESTABLISHED) {
            asoc->assoc_id = new->assoc_id;
            asoc->ssnmap = new->ssnmap;
        }
    }

    /* Update AUTH related parameters */
    if (new->auth_info) {
        asoc->auth_info = new->auth_info;
        asoc->auth_num = new->auth_num;
        sctp_copy_auth_keys(asoc, new);
    }
}

void sctp_update_association(struct sctp_association *asoc, struct sctp_association *new) {
    struct sctp_transport *t, *tmp;

    /* Copy new parameters from 'new' to 'asoc' */
    asoc->rwnd = new->rwnd;
    asoc->ssthresh = new->ssthresh;
    asoc->c.sACKdelay = new->c.sACKdelay;
    asoc->c.sACKfreq = new->c.sACKfreq;
    asoc->c.sinit_max_init_attempts = new->c.sinit_max_init_attempts;
    asoc->c.sinit_max_init_timeo = new->c.sinit_max_init_timeo;
    asoc->c.sinit_max_outstreams = new->c.sinit_max_outstreams;
    asoc->c.sinit_num_ostreams = new->c.sinit_num_ostreams;

    /* Remove peer addresses not present in the new association */
    list_for_each_entry_safe(t, tmp, &asoc->peer.transport_addr_list, transport_list) {
        int found = 0;
        struct sctp_transport *t2;

        list_for_each_entry(t2, &new->peer.transport_addr_list, transport_list) {
            if (sctp_cmp_addr((struct sctp_sockaddr *)&t->addr, (struct sctp_sockaddr *)&t2->addr) == 0) {
                found = 1;
                break;
            }
        }

        if (!found) {
            list_del(&t->transport_list);
            kfree(t);
        }
    }

    /* Add new peer addresses if association is not established */
    if (asoc->state != SCTP_ESTABLISHED) {
        struct sctp_transport *t2;

        list_for_each_entry(t2, &new->peer.transport_addr_list, transport_list) {
            int found = 0;
            struct sctp_transport *t;

            list_for_each_entry(t, &asoc->peer.transport_addr_list, transport_list) {
                if (sctp_cmp_addr((struct sctp_sockaddr *)&t->addr, (struct sctp_sockaddr *)&t2->addr) == 0) {
                    found = 1;
                    break;
                }
            }

            if (!found) {
                t = kmalloc(sizeof(*t), GFP_KERNEL);
                if (t) {
                    memcpy(&t->addr, &t2->addr, sizeof(t->addr));
                    list_add_tail(&t->transport_list, &asoc->peer.transport_addr_list);
                }
            }
        }
    }

    /* If established, update next TSN and clear SSN map */
    if (asoc->state == SCTP_ESTABLISHED) {
        asoc->c.tsn_next = new->c.tsn_next;
        sctp_ssnmap_clear(&asoc->ssnmap);
        sctp_ulpeventq_flush(&asoc->ulpq);
        asoc->error_count = 0;
    }

    /* Update SCTP-AUTH related peer parameters */
    if (new->authenticator) {
        if (asoc->authenticator) {
            kfree(asoc->authenticator);
        }
        asoc->authenticator = kmemdup(new->authenticator, sizeof(*asoc->authenticator), GFP_KERNEL);
        asoc->shared_key = new->shared_key;
    }
}

void sctp_association_update(struct sctp_association *asoc, struct sctp_association *new) {
    /* Copy new parameters from 'new' to 'asoc' */
    asoc->rwnd = new->rwnd;
    asoc->mtu = new->mtu;
    asoc->inbound_streams = new->inbound_streams;
    asoc->outbound_streams = new->outbound_streams;

    /* Remove addresses in asoc not present in new */
    struct sctp_sockaddr *tmp, *addr;
    sctp_list_for_each_entry_safe(addr, tmp, &asoc->peer_addrs, list) {
        int found = 0;
        sctp_list_for_each_entry(addr, &new->peer_addrs, list) {
            if (memcmp(&addr->addr, &addr->addr, sizeof(struct sockaddr)) == 0) {
                found = 1;
                break;
            }
        }
        if (!found) {
            sctp_list_del(&addr->list);
            free(addr);
        }
    }

    if (asoc->state == SCTP_STATE_ESTABLISHED) {
        asoc->next_tsn = new->next_tsn;
        sctp_ssn_map_clear(asoc->ssn_map);
        sctp_flush_ulp_reasm(asoc);
        asoc->error_count = 0;
    } else {
        sctp_list_splice(&new->peer_addrs, &asoc->peer_addrs);
        if (asoc->ssn_map) {
            sctp_ssn_map_destroy(asoc->ssn_map);
        }
        asoc->ssn_map = new->ssn_map;
        new->ssn_map = NULL;
        asoc->assoc_id = new->assoc_id;
    }

    /* Copy over SCTP-AUTH related parameters */
    asoc->auth_key = new->auth_key;
    asoc->auth_key_len = new->auth_key_len;
    asoc->auth_keys = new->auth_keys;
    asoc->auth_key_count = new->auth_key_count;
    new->auth_key = NULL;
    new->auth_key_len = 0;
}
